import{_ as i,c as e,o,ag as a}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"OPDW C100 Multi-Mission Platform","description":"","frontmatter":{"title":"OPDW C100 Multi-Mission Platform"},"headers":[],"relativePath":"general/opdw-c100-multi-mission-platform.md","filePath":"general/opdw-c100-multi-mission-platform.md","lastUpdated":null}'),n={name:"general/opdw-c100-multi-mission-platform.md"};function s(r,t,l,p,d,m){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="opdw-c100-multi-mission-platform" tabindex="-1">OPDW C100 Multi-Mission Platform <a class="header-anchor" href="#opdw-c100-multi-mission-platform" aria-label="Permalink to &quot;OPDW C100 Multi-Mission Platform&quot;">​</a></h1><h2 id="opdw-c100-multi-mission-platform-1" tabindex="-1">OPDW C100 Multi-Mission Platform <a class="header-anchor" href="#opdw-c100-multi-mission-platform-1" aria-label="Permalink to &quot;OPDW C100 Multi-Mission Platform&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The OPDW C100 is a multi-mission platform equipped with military-grade payloads, advanced drivetrain, and Blue UAS approved avionics. It offers long-endurance organic ISR capabilities, edge computing, and a suite of autonomy features aimed at reducing cognitive burden and providing hands-free functionality. Its ruggedized IP54 design allows for easy transportation by folding into a compact form.</p><p><em>[pdw-c100.jpeg]</em></p><h3 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h3><ul><li><p><strong>Folded / Unfolded Dimensions:</strong> 24” x 15” x 8” / 64” x 65” x 11”</p></li><li><p><strong>Weight:</strong> 21.4 lbs (9.7 kg)</p></li><li><p><strong>Max Payload Mass:</strong> Up to 10 lbs (4.5 kg) with Long Endurance Pack (LEP) batteries</p></li><li><p><strong>Long Endurance Battery:</strong> 74 minutes with ISR payload</p></li><li><p><strong>Range:</strong> 6.2+ miles (10+ km)</p></li><li><p><strong>Cruise Speed:</strong> 22.3 mph (36 km/h)</p></li><li><p><strong>Max Speed:</strong> 40 mph (64.8 km/h)</p></li><li><p><strong>Wind Limits:</strong></p></li><li><p>&#39; 30 mph sustained, 40 mph gust (ISR configuration)</p></li><li><p>&#39; 25 mph sustained, 35 mph gust (up to 5 lbs gross payload weight)</p></li></ul><ul><li>20 mph sustained, 30 mph gust (up to 10 lbs gross payload weight)</li></ul><ul><li><p><strong>Night Operations:</strong> Zero light emission mode with IR LEDs and strobe lights</p></li><li><p><strong>Acoustic Signature:</strong> 61dB @ 5m away / non-audible at 600 meters</p></li><li><p><strong>Autonomy:</strong> Visual Point Hold, Collision Prevention, Object Detection</p></li><li><p><strong>Compute Core:</strong> Modal AI’s VOXL1 Qualcomm 812 + optional Nvidia Xavier NX</p></li><li><p><strong>Weatherization:</strong> IP54</p></li><li><p><strong>Supply Chain:</strong> NDAA Compliant / Blue UAS</p></li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li><p><strong>Flight Time:</strong></p></li><li><p>&#39; 80 minutes at 2 lbs payload</p></li><li><p>&#39; 70 minutes at 4 lbs payload</p></li><li><p>&#39; 60 minutes at 6 lbs payload</p></li><li><p>&#39; 50 minutes at 8 lbs payload</p></li></ul><ul><li>40 minutes at 10 lbs payload</li></ul><h3 id="questions-to-ask-at-demonstration" tabindex="-1">Questions to Ask at Demonstration <a class="header-anchor" href="#questions-to-ask-at-demonstration" aria-label="Permalink to &quot;Questions to Ask at Demonstration&quot;">​</a></h3><ol><li><p><strong>Visibility and Detection:</strong> #* How far away can the C100 be seen by enemies? #* What are its IR and thermal signatures? #* What is the acoustic signature in different operational modes?</p></li><li><p><strong>Data and Communication:</strong> #* What are the bandwidth requirements for usable FMV feeds from the sensor to the operator? #* How is sensitive data managed on the drone? Is there local hosting or a store-and-forward mechanism that zeroizes upon impact? #* Is telemetry parsed in a separate channel to facilitate multi-enclave / shareable classification products when working with partner forces?</p></li><li><p><strong>Battery and Power:</strong> #* Are the batteries proprietary? What is their lifespan and chemistry? #* How does the drone perform in different environmental conditions such as winter, ice, rain, and high winds? #* Is saltwater exposure an issue? How does it handle dust storms?</p></li><li><p><strong>Durability and Maintenance:</strong> #* What is the most commonly broken part, and should we stock spare parts in advance? #* Is there a 24/7/365 manned hotline for support, reachable via public VOIP?</p></li><li><p><strong>Operational Use:</strong> #* Has the product been used in a theater of war, and by whom? #* Can we get contact information for those users to discuss their experiences? #* Can the drone be flown during the demonstration?</p></li><li><p><strong>Cost and Support:</strong> #* What is the price for the drone, ground control station (GCS), and enough batteries for continuous operation? #* How is sensitive data secured on the drone, especially considering potential capture by adversaries?</p></li></ol><h3 id="notes-from-prior-demonstrations" tabindex="-1">Notes from Prior Demonstrations <a class="header-anchor" href="#notes-from-prior-demonstrations" aria-label="Permalink to &quot;Notes from Prior Demonstrations&quot;">​</a></h3><ul><li><p>The C100 is considered as good as it gets for current US DoD applications, particularly for GWOT operations.</p></li><li><p>Not yet suitable for LSCO until frequency hopping radios and relay systems are integrated.</p></li><li><p>Solid support for non-DoD CONUS operations.</p></li></ul>',16)])])}const c=i(n,[["render",s]]);export{h as __pageData,c as default};
